// ETAPA 3: Heurística Verbal para Hobbies
// FASE 3: Hobby Gate - Bloqueia verbos genéricos

interface HobbyVerbResult {
  decision: 'ALLOW' | 'DENY';
  reasonCode?: string;
  suggestion?: string;
}

class HobbyVerbHeuristicService {
  // Verbos genéricos que devem ser bloqueados no início
  private readonly BLOCKED_START_VERBS = new Set([
    'ligar',
    'mexer',
    'usar',
    'abrir',
    'entrar',
    'ficar',
    'acessar',
    'clicar',
    'tocar', // "tocar" sozinho é genérico, mas "tocar violão" é válido
    'jogar', // "jogar" sozinho é genérico, mas "jogar xadrez" é válido
    'assistir', // "assistir" sozinho é genérico, mas "assistir filmes" pode ser válido
  ]);

  // Gerúndios genéricos que devem ser bloqueados no final
  private readonly BLOCKED_END_GERUNDS = new Set([
    'jogando',
    'mexendo',
    'assistindo',
    'usando',
    'abrindo',
    'entrando',
    'ficando',
    'acessando',
    'clicando',
  ]);

  /**
   * Normaliza input para comparação
   */
  private normalizeInput(input: string): string {
    return input
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .trim();
  }

  /**
   * Divide texto em palavras
   */
  private splitWords(text: string): string[] {
    return text
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .split(/\s+/)
      .filter(word => word.length > 0);
  }

  /**
   * Verifica se começa com verbo genérico bloqueado
   */
  private startsWithBlockedVerb(normalized: string, words: string[]): boolean {
    if (words.length === 0) return false;
    
    const firstWord = words[0];
    
    // Se começa com verbo bloqueado E não tem objeto válido (apenas 1 palavra ou 2 palavras sem sentido)
    if (this.BLOCKED_START_VERBS.has(firstWord)) {
      // Se tem apenas 1 palavra, bloquear
      if (words.length === 1) {
        return true;
      }
      
      // Se tem 2 palavras mas a segunda é genérica, bloquear
      if (words.length === 2) {
        const secondWord = words[1];
        const genericObjects = ['videogame', 'celular', 'computador', 'telefone', 'tablet', 'app', 'aplicativo', 'site', 'internet', 'rede', 'social'];
        if (genericObjects.includes(secondWord)) {
          return true;
        }
      }
    }
    
    return false;
  }

  /**
   * Verifica se termina com gerúndio genérico bloqueado
   */
  private endsWithBlockedGerund(normalized: string, words: string[]): boolean {
    if (words.length === 0) return false;
    
    const lastWord = words[words.length - 1];
    
    // Se termina com gerúndio bloqueado
    if (this.BLOCKED_END_GERUNDS.has(lastWord)) {
      return true;
    }
    
    return false;
  }

  /**
   * Valida heurística verbal para hobbies
   * 
   * BLOQUEIA:
   * - "ligar videogame"
   * - "mexer no celular"
   * - "ficar no computador"
   * - "abrir instagram"
   * - "jogando" (sem objeto)
   * 
   * PERMITE (será validado pelo HobbyMatcher):
   * - "tocar violão" (verbo + objeto válido)
   * - "jogar xadrez" (verbo + objeto válido)
   * - "praticar ioga" (verbo + objeto válido)
   */
  validate(input: string): HobbyVerbResult {
    const normalized = this.normalizeInput(input);
    const words = this.splitWords(normalized);

    // Bloquear se começar com verbo genérico
    if (this.startsWithBlockedVerb(normalized, words)) {
      return {
        decision: 'DENY',
        reasonCode: 'GENERIC_VERB_BLOCKED',
        suggestion: 'Use o nome específico do hobby (ex: "xadrez", "fotografia", "tocar violão", "jogar xadrez")',
      };
    }

    // Bloquear se terminar com gerúndio genérico
    if (this.endsWithBlockedGerund(normalized, words)) {
      return {
        decision: 'DENY',
        reasonCode: 'GENERIC_GERUND_BLOCKED',
        suggestion: 'Use o nome específico do hobby (ex: "xadrez", "fotografia", "tocar violão")',
      };
    }

    // Permitir - será validado pelo HobbyMatcher
    return {
      decision: 'ALLOW',
    };
  }
}

export const hobbyVerbHeuristicService = new HobbyVerbHeuristicService();
export type { HobbyVerbResult };




























